from typing import Tuple, List
import numpy as np
import pandas as pd
from solver import Algorithm


class Evolved(Algorithm):
    """Lossless, bounded character-prefix ordering optimizer."""

    def __init__(self, df: pd.DataFrame = None):
        self.df = df
        self.num_rows = 0
        self.num_cols = 0

    @staticmethod
    def _cell_text(value) -> str:
        try:
            missing = pd.isna(value)
            if isinstance(missing, (bool, np.bool_)) and bool(missing):
                return ""
        except Exception:
            pass
        return str(value)

    @staticmethod
    def _lcp(a: str, b: str) -> int:
        hi = min(len(a), len(b))
        if hi == 0:
            return 0
        lo = 0
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if a[:mid] == b[:mid]:
                lo = mid
            else:
                hi = mid - 1
        return lo

    @classmethod
    def _trie_score(cls, strings: List[str]) -> int:
        if len(strings) < 2:
            return 0
        strings = sorted(strings)
        total = 0
        previous = strings[0]
        for current in strings[1:]:
            total += cls._lcp(previous, current)
            previous = current
        return total

    @staticmethod
    def _serialize(cells, orders):
        return [
            "".join(cells[row, col] for col in orders[row])
            for row in range(cells.shape[0])
        ]

    def _column_stats(self, cells):
        n, m = cells.shape
        weighted = np.zeros(m, dtype=np.int64)
        repetition = np.zeros(m, dtype=np.int64)
        codes = []
        for col in range(m):
            mapping = {}
            col_codes = np.empty(n, dtype=np.int32)
            counts = []
            lengths = []
            next_code = 0
            for row, value in enumerate(cells[:, col]):
                code = mapping.get(value)
                if code is None:
                    code = next_code
                    mapping[value] = code
                    next_code += 1
                    counts.append(0)
                    lengths.append(len(value))
                col_codes[row] = code
                counts[code] += 1
            w = 0
            r = 0
            for count, length in zip(counts, lengths):
                r += count * (count - 1)
                w += length * count * (count - 1)
            weighted[col] = w
            repetition[col] = r
            codes.append(col_codes)
        return codes, weighted, repetition

    @staticmethod
    def _rank(weighted, repetition, mode):
        m = len(weighted)
        if mode == 0:
            return sorted(range(m), key=lambda c: (-int(weighted[c]), c))
        return sorted(
            range(m),
            key=lambda c: (-(int(weighted[c]) + int(repetition[c])), c),
        )

    def _conditional_tree(self, cells, codes, global_order):
        n, m = cells.shape
        result = [None] * n
        max_depth = 3
        work = [0]
        work_limit = max(n, 4 * n)
        rank_pos = {c: i for i, c in enumerate(global_order)}

        def local_score(rows, col):
            counts = {}
            for row in rows:
                code = int(codes[col][row])
                counts[code] = counts.get(code, 0) + 1
            score = 0
            for row in rows:
                code = int(codes[col][row])
                count = counts[code]
                if count > 1:
                    score += len(cells[row, col]) * (count - 1)
            return score

        def finish(rows, prefix, remaining):
            tail = sorted(remaining, key=lambda c: rank_pos[c])
            order = prefix + tail
            for row in rows:
                result[row] = order[:]

        def visit(rows, prefix, remaining, depth):
            if (depth >= max_depth or len(rows) < 3 or not remaining or
                    work[0] + len(rows) > work_limit):
                finish(rows, prefix, remaining)
                return

            # Considering only the globally strongest remaining columns bounds
            # work on very wide frames without affecting permutation validity.
            candidates = sorted(
                remaining, key=lambda c: rank_pos[c]
            )[:min(16, len(remaining))]
            best_col = None
            best_score = 0
            for col in candidates:
                score = local_score(rows, col)
                if score > best_score or (
                    score == best_score and best_col is not None and col < best_col
                ):
                    best_score = score
                    best_col = col
            if best_col is None or best_score <= 0:
                finish(rows, prefix, remaining)
                return

            work[0] += len(rows)
            groups = {}
            column_codes = codes[best_col]
            for row in rows:
                groups.setdefault(int(column_codes[row]), []).append(row)
            if len(groups) <= 1:
                finish(rows, prefix, remaining)
                return

            rest = [c for c in remaining if c != best_col]
            for group_rows in groups.values():
                visit(group_rows, prefix + [best_col], rest, depth + 1)

        visit(list(range(n)), [], list(range(m)), 0)
        for row in range(n):
            if result[row] is None:
                result[row] = global_order[:]
        return result

    def _candidate(self, cells, orders):
        strings = self._serialize(cells, orders)
        score = self._trie_score(strings)
        row_order = sorted(range(len(strings)), key=lambda r: (strings[r], r))
        return score, row_order

    def reorder(
        self,
        df: pd.DataFrame,
        early_stop: int = 0,
        row_stop: int = None,
        col_stop: int = None,
        col_merge=[],
        one_way_dep=[],
        distinct_value_threshold=0.8,
        parallel=True,
    ) -> Tuple[pd.DataFrame, List[List[str]]]:
        n, m = df.shape
        self.num_rows = n
        self.num_cols = m

        if n == 0 or m == 0:
            return df.copy(), [[] for _ in range(n)]

        raw = df.to_numpy(dtype=object, copy=True)
        cells = np.empty((n, m), dtype=object)
        for row in range(n):
            for col in range(m):
                cells[row, col] = self._cell_text(raw[row, col])

        codes, weighted, repetition = self._column_stats(cells)
        global_a = self._rank(weighted, repetition, 0)
        global_b = self._rank(weighted, repetition, 1)
        conditional = self._conditional_tree(cells, codes, global_a)

        candidates = (
            [global_a[:] for _ in range(n)],
            [global_b[:] for _ in range(n)],
            conditional,
        )

        best_score = -1
        best_rows = None
        best_orders = None
        for orders in candidates:
            score, row_order = self._candidate(cells, orders)
            if score > best_score:
                best_score = score
                best_rows = row_order
                best_orders = orders

        output = np.empty((n, m), dtype=object)
        column_orders = []
        for destination, source in enumerate(best_rows):
            order = best_orders[source]
            output[destination, :] = [raw[source, col] for col in order]
            column_orders.append([df.columns[col] for col in order])

        return pd.DataFrame(output, columns=df.columns), column_orders

